def propose(ctx):
    time_s = ctx['time_s']
    start = ctx['satellite_window']['start']
    end = ctx['satellite_window']['end']
    if time_s < max(0, start - 120) or time_s > end:
        return {'roles': [], 'reason': 'outside planning window'}
    units = ctx['units']
    targets = ctx['targets']
    reqs = ctx['public_requirements']
    orders = ctx['baseline_orders']
    budget = {}
    for u, v in units.items():
        src = orders.get(u, {}).get('target_ref', v.get('target'))
        typ = reqs.get(src, {}).get('type')
        if typ != 9400 and typ != 9600:
            continue
        if v['role'] == 'H':
            damage = 9.6 if typ == 9400 else 12.0
        elif v['role'] == 'M':
            damage = 2.4 if typ == 9400 else 3.0
        else:
            continue
        budget[src] = budget.get(src, 0.0) + damage
    best = None
    best_gap = -1.0
    best_eta = 100000.0
    for dest, target in targets.items():
        if target['type'] != 9600 or not target.get('freshness_known'):
            continue
        age = target.get('age_s')
        if age is None or age < 0 or age > 5:
            continue
        hp = reqs.get(dest, {}).get('initial_health')
        if hp is None:
            continue
        gap = hp - budget.get(dest, 0.0)
        if gap <= 0:
            continue
        for u, v in units.items():
            if v['role'] != 'H' or u in orders:
                continue
            src = v.get('target')
            if src == dest or src not in reqs:
                continue
            src_type = reqs[src]['type']
            if src_type != 9400 and src_type != 9600:
                continue
            removal = 9.6 if src_type == 9400 else 12.0
            if budget.get(src, 0.0) - removal + 0.00000001 < reqs[src]['initial_health']:
                continue
            eta = distance(v['position'], target['position']) / 200.0 * 1.08 + 12.0
            if eta >= v['remaining_s'] - 60 or time_s + eta < start or time_s + eta > end:
                continue
            if gap > best_gap or (gap == best_gap and eta < best_eta):
                best = {'unit': u, 'target': dest, 'duty': 'redirect one H to sentry coverage gap'}
                best_gap = gap
                best_eta = eta
    if best is None:
        return {'roles': [], 'reason': 'no safe reachable pair in estimated window'}
    return {'roles': [best], 'reason': 'estimated arrival inside planned satellite window; preserve conservative source coverage'}
